import csv
from collections import defaultdict
vals=defaultdict(list)
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        vals[r['timeseries_id']].append((r['timestamp'], float(r['value'])))

P1=('2018-01-01T00:00:00','2018-07-01T00:00:00')
P2=('2018-07-01T00:00:00','2019-01-01T00:00:00')

rows=list(csv.DictReader(open(CATALOG_CSV)))
by_point={r['point_uri'].split('#')[-1]:r['timeseries_id'] for r in rows}

def stats(ts, lo, hi):
    if not ts: return None
    xs=sorted(v for t,v in vals[ts] if lo<=t<=hi)
    n=len(xs); mean=sum(xs)/n
    return round(min(xs),2), round(max(xs),2), round(mean,2), round(xs[n//2],2)

zones=[f'F{i}_Z0{j}' for i in range(1,6) for j in range(1,6)]
print('TEMP')
for z in zones:
    key=f'Zone_{z}.Zone_Air_Temperature_Sensor'
    if key in by_point:
        ts=by_point[key]
        print(z, stats(ts,*P1), '->', stats(ts,*P2))
    else:
        print(z, 'NO SENSOR')
print('DAMPER (VAV cooling demand proxy)')
for z in zones:
    key=f'VAV_{z}.Damper_Position_Setpoint'
    if key in by_point:
        ts=by_point[key]
        print(z, stats(ts,*P1), '->', stats(ts,*P2))
    else:
        print(z, 'NO VAV')
